<?php
namespace App\Models;
use App\Enums\{CmsPageStatus,CmsPageType}; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Builder;
class CmsPage extends Model { protected $fillable=['title','slug','page_type','excerpt','content','status','published_at','seo_title','seo_description','template','show_in_header','show_in_footer','sort_order','created_by','updated_by','is_system','translations']; protected function casts():array{return ['page_type'=>CmsPageType::class,'status'=>CmsPageStatus::class,'published_at'=>'datetime','show_in_header'=>'boolean','show_in_footer'=>'boolean','sort_order'=>'integer','is_system'=>'boolean','translations'=>'array'];} public function getLocalizedTitleAttribute():string{return data_get($this->translations,app()->getLocale().'.title',$this->title);} public function getLocalizedContentAttribute():?string{return data_get($this->translations,app()->getLocale().'.content',$this->content);} public function sections():HasMany{return $this->hasMany(CmsPageSection::class)->orderBy('sort_order')->orderBy('id');} public function scopePublic(Builder $q):Builder{return $q->where('status',CmsPageStatus::Published)->where(fn($q)=>$q->whereNull('published_at')->orWhere('published_at','<=',now()));} public function derivedStatus():string{return $this->status===CmsPageStatus::Draft?'Draft':($this->published_at&&$this->published_at->isFuture()?'Scheduled':'Published');} }
